pub fn validate_user_registration(
    username: &str,
    email: &str,
    password: &str,
    confirm_password: &str,
    age: u32,
    country: &str,
    terms_accepted: bool,
) -> Result<User, ValidationError> {
    if username.is_empty() {
        return Err(ValidationError::EmptyField("username"));
    }
    if username.len() < 3 {
        return Err(ValidationError::TooShort("username", 3));
    }
    if username.len() > 32 {
        return Err(ValidationError::TooLong("username", 32));
    }
    if !username.chars().all(|c| c.is_alphanumeric() || c == '_') {
        return Err(ValidationError::InvalidChars("username"));
    }
    if email.is_empty() {
        return Err(ValidationError::EmptyField("email"));
    }
    if !email.contains('@') {
        return Err(ValidationError::InvalidFormat("email"));
    }
    let parts: Vec<&str> = email.split('@').collect();
    if parts.len() != 2 {
        return Err(ValidationError::InvalidFormat("email"));
    }
    if parts[1].split('.').count() < 2 {
        return Err(ValidationError::InvalidFormat("email"));
    }
    if password.is_empty() {
        return Err(ValidationError::EmptyField("password"));
    }
    if password.len() < 8 {
        return Err(ValidationError::TooShort("password", 8));
    }
    if password.len() > 128 {
        return Err(ValidationError::TooLong("password", 128));
    }
    if !password.chars().any(|c| c.is_uppercase()) {
        return Err(ValidationError::MissingRequirement("uppercase letter"));
    }
    if !password.chars().any(|c| c.is_lowercase()) {
        return Err(ValidationError::MissingRequirement("lowercase letter"));
    }
    if !password.chars().any(|c| c.is_numeric()) {
        return Err(ValidationError::MissingRequirement("digit"));
    }
    if !password.chars().any(|c| !c.is_alphanumeric()) {
        return Err(ValidationError::MissingRequirement("special character"));
    }
    if password != confirm_password {
        return Err(ValidationError::PasswordMismatch);
    }
    if age < 13 {
        return Err(ValidationError::TooYoung(13));
    }
    if age > 150 {
        return Err(ValidationError::InvalidAge);
    }
    let banned_countries = ["XX", "YY", "ZZ"];
    if banned_countries.contains(&country) {
        return Err(ValidationError::BannedCountry(country.to_string()));
    }
    if country.len() != 2 {
        return Err(ValidationError::InvalidFormat("country code"));
    }
    if !terms_accepted {
        return Err(ValidationError::TermsNotAccepted);
    }
    let hashed_password = hash_password(password);
    let user = User {
        username: username.to_string(),
        email: email.to_string(),
        password_hash: hashed_password,
        age,
        country: country.to_string(),
        created_at: chrono::Utc::now(),
    };
    Ok(user)
}

async function submitApplication(
  firstName: string,
  lastName: string,
  email: string,
  phone: string,
  position: string,
  department: string,
  salaryExpectation: number,
  startDate: Date,
  coverLetter: string,
): Promise<ApplicationResult> {
  const payload = {
    firstName,
    lastName,
    email,
    phone,
    position,
    department,
    salaryExpectation,
    startDate: startDate.toISOString(),
    coverLetter,
  };
