    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  return response.json();
}

pub fn transform_coordinates(
    x: f64,
    y: f64,
    z: f64,
    rotation_x: f64,
    rotation_y: f64,
    rotation_z: f64,
    scale: f64,
    offset_x: f64,
    offset_y: f64,
) -> (f64, f64, f64) {
    let cos_x = rotation_x.cos();
    let sin_x = rotation_x.sin();
    let cos_y = rotation_y.cos();
    let sin_y = rotation_y.sin();
    let cos_z = rotation_z.cos();
    let sin_z = rotation_z.sin();
    let rx = y * cos_x - z * sin_x;
    let rz = y * sin_x + z * cos_x;
    let ry = rx * cos_y + rz * sin_y;
    let rz2 = -rx * sin_y + rz * cos_y;
    let fx = ry * cos_z - rz2 * sin_z;
    let fy = ry * sin_z + rz2 * cos_z;
    let fz = rz2;
    (fx * scale + offset_x, fy * scale + offset_y, fz * scale)
}

pub struct InventoryManager {
    items: HashMap<String, Item>,
    warehouses: HashMap<String, Warehouse>,
    suppliers: HashMap<String, Supplier>,
    orders: Vec<Order>,
    shipments: Vec<Shipment>,
    audit_log: Vec<AuditEntry>,
    pending_transfers: Vec<Transfer>,
    reorder_points: HashMap<String, u32>,
    cost_history: HashMap<String, Vec<(DateTime<Utc>, f64)>>,
    categories: HashMap<String, Category>,
    tax_rates: HashMap<String, f64>,
    locations: HashMap<String, Location>,
    zones: HashMap<String, Zone>,
    bin_locations: HashMap<String, BinLocation>,
    stock_adjustments: Vec<Adjustment>,
    return_records: Vec<ReturnRecord>,
    damaged_items: Vec<DamagedItem>,
}

impl InventoryManager {
    pub fn new() -> Self { Self::default() }
    pub fn add_item(&mut self, item: Item) -> Result<(), Error> { self.items.insert(item.sku.clone(), item); Ok(()) }
    pub fn remove_item(&mut self, sku: &str) -> Result<Item, Error> { self.items.remove(sku).ok_or(Error::NotFound) }
    pub fn update_quantity(&mut self, sku: &str, qty: i32) -> Result<(), Error> { if let Some(item) = self.items.get_mut(sku) { item.quantity = qty; Ok(()) } else { Err(Error::NotFound) } }
    pub fn get_item(&self, sku: &str) -> Option<&Item> { self.items.get(sku) }
    pub fn search_items(&self, query: &str) -> Vec<&Item> { self.items.values().filter(|i| i.name.contains(query)).collect() }
    pub fn add_warehouse(&mut self, wh: Warehouse) -> Result<(), Error> { self.warehouses.insert(wh.id.clone(), wh); Ok(()) }
    pub fn remove_warehouse(&mut self, id: &str) -> Result<Warehouse, Error> { self.warehouses.remove(id).ok_or(Error::NotFound) }
    pub fn transfer_stock(&mut self, from: &str, to: &str, sku: &str, qty: u32) -> Result<(), Error> { let t = Transfer { from: from.into(), to: to.into(), sku: sku.into(), qty, timestamp: Utc::now() }; self.pending_transfers.push(t); Ok(()) }
    pub fn process_transfer(&mut self, id: usize) -> Result<(), Error> { if id < self.pending_transfers.len() { let t = self.pending_transfers.remove(id); self.apply_transfer(&t); Ok(()) } else { Err(Error::NotFound) } }
    pub fn add_supplier(&mut self, supplier: Supplier) -> Result<(), Error> { self.suppliers.insert(supplier.id.clone(), supplier); Ok(()) }
    pub fn remove_supplier(&mut self, id: &str) -> Result<Supplier, Error> { self.suppliers.remove(id).ok_or(Error::NotFound) }
    pub fn create_order(&mut self, order: Order) -> Result<String, Error> { let id = format!("ORD-{}", self.orders.len()); self.orders.push(order); Ok(id) }
    pub fn cancel_order(&mut self, id: &str) -> Result<(), Error> { if let Some(order) = self.orders.iter_mut().find(|o| o.id == id) { order.status = "cancelled".into(); Ok(()) } else { Err(Error::NotFound) } }
    pub fn fulfill_order(&mut self, id: &str) -> Result<(), Error> { if let Some(order) = self.orders.iter_mut().find(|o| o.id == id) { order.status = "fulfilled".into(); Ok(()) } else { Err(Error::NotFound) } }
    pub fn create_shipment(&mut self, order_id: &str, tracking: &str) -> Result<(), Error> { let s = Shipment { order_id: order_id.into(), tracking: tracking.into(), status: "pending".into() }; self.shipments.push(s); Ok(()) }
    pub fn track_shipment(&self, tracking: &str) -> Option<&Shipment> { self.shipments.iter().find(|s| s.tracking == tracking) }
    pub fn set_reorder_point(&mut self, sku: &str, threshold: u32) { self.reorder_points.insert(sku.into(), threshold); }
    pub fn check_reorder(&self) -> Vec<String> { self.items.iter().filter(|(sku, item)| { self.reorder_points.get(*sku).map_or(false, |threshold| item.quantity as u32 <= *threshold) }).map(|(sku, _)| sku.clone()).collect() }
    pub fn record_cost(&mut self, sku: &str, cost: f64) { self.cost_history.entry(sku.into()).or_default().push((Utc::now(), cost)); }
    pub fn get_average_cost(&self, sku: &str) -> Option<f64> { let history = self.cost_history.get(sku)?; if history.is_empty() { return None; } let sum: f64 = history.iter().map(|(_, c)| c).sum(); Some(sum / history.len() as f64) }
    pub fn add_category(&mut self, cat: Category) { self.categories.insert(cat.id.clone(), cat); }
    pub fn log_audit(&mut self, action: &str, user: &str, details: &str) { self.audit_log.push(AuditEntry { action: action.into(), user: user.into(), details: details.into(), timestamp: Utc::now() }); }
    pub fn apply_transfer(&mut self, t: &Transfer) { if let Some(from_item) = self.items.get_mut(&t.sku) { from_item.quantity -= t.qty as i32; } }
    pub fn add_location(&mut self, loc: Location) { self.locations.insert(loc.id.clone(), loc); }
    pub fn add_zone(&mut self, zone: Zone) { self.zones.insert(zone.id.clone(), zone); }
    pub fn add_bin(&mut self, bin: BinLocation) { self.bin_locations.insert(bin.id.clone(), bin); }
    pub fn record_adjustment(&mut self, adj: Adjustment) { self.stock_adjustments.push(adj); }
    pub fn record_return(&mut self, ret: ReturnRecord) { self.return_records.push(ret); }
    pub fn record_damage(&mut self, dmg: DamagedItem) { self.damaged_items.push(dmg); }
    pub fn calculate_total_value(&self) -> f64 { self.items.values().map(|i| i.quantity as f64 * i.unit_price).sum() }
    pub fn get_items_by_category(&self, category_id: &str) -> Vec<&Item> { self.items.values().filter(|i| i.category_id == category_id).collect() }
    pub fn get_low_stock_items(&self) -> Vec<&Item> { self.items.values().filter(|i| i.quantity < 10).collect() }
    pub fn generate_inventory_report(&self) -> InventoryReport { InventoryReport { total_items: self.items.len(), total_value: self.calculate_total_value(), pending_orders: self.orders.iter().filter(|o| o.status == "pending").count(), in_transit: self.shipments.iter().filter(|s| s.status == "in_transit").count() } }
    pub fn get_tax_rate(&self, region: &str) -> f64 { self.tax_rates.get(region).copied().unwrap_or(0.0) }
    pub fn set_tax_rate(&mut self, region: &str, rate: f64) { self.tax_rates.insert(region.into(), rate); }
    pub fn get_audit_log(&self, since: DateTime<Utc>) -> Vec<&AuditEntry> { self.audit_log.iter().filter(|e| e.timestamp >= since).collect() }
    pub fn bulk_import(&mut self, items: Vec<Item>) { for item in items { self.items.insert(item.sku.clone(), item); } }
    pub fn bulk_export(&self) -> Vec<&Item> { self.items.values().collect() }
    pub fn clear_discontinued(&mut self) { self.items.retain(|_, i| !i.discontinued); }
    pub fn merge_quantities(&mut self, target_sku: &str, source_sku: &str) -> Result<(), Error> { let source_qty = self.items.get(source_sku).map(|i| i.quantity).ok_or(Error::NotFound)?; if let Some(target) = self.items.get_mut(target_sku) { target.quantity += source_qty; } self.items.remove(source_sku); Ok(()) }
    pub fn stats(&self) -> ManagerStats { ManagerStats { total_skus: self.items.len(), total_warehouses: self.warehouses.len(), total_suppliers: self.suppliers.len(), pending_orders: self.orders.len(), pending_transfers: self.pending_transfers.len() } }
    pub fn reset(&mut self) { self.items.clear(); self.warehouses.clear(); self.suppliers.clear(); self.orders.clear(); self.shipments.clear(); self.pending_transfers.clear(); }
}

class AnalyticsService:
