/**
 * Parses a CSV line into its constituent fields.
 *
 * <p>This method handles quoted fields, escaped quotes within fields,
 * and variable-length records. It follows RFC 4180 for CSV parsing
 * with the following considerations:</p>
 *
 * <ul>
 *   <li>Fields containing commas must be quoted</li>
 *   <li>Fields containing newlines must be quoted</li>
 *   <li>Fields containing double quotes must have them escaped</li>
 *   <li>Leading/trailing whitespace is preserved in quoted fields</li>
 * </ul>
 *
 * <h3>Implementation Notes:</h3>
 * <p>The parser uses a state machine with the following states:
 * START, IN_FIELD, IN_QUOTE, QUOTE_IN_QUOTE. Transitions
 * happen on comma, quote, and end-of-line characters.</p>
 *
 * @param line the CSV line to parse, must not be null
 * @param delimiter the field delimiter character, typically ','
 * @param quoteChar the quote character, typically '"'
 * @param escapeChar the escape character, typically '\\'
 * @return a list of parsed fields in order of appearance
 * @throws IllegalArgumentException if line is null
 * @throws CsvParseException if the line has unterminated quotes
 *
 * @see CsvParser#parse(InputStream)
 * @see CsvParser#parse(Reader)
 * @since 2.0
 * @deprecated Use {@link #parseLine(String, CsvFormat)} instead
 */
public List<String> parseLine(String line, char delimiter, char quoteChar, char escapeChar) {
    // Validate input - line cannot be null
    if (line == null) {
        throw new IllegalArgumentException("Line cannot be null");
    }

    // Initialize result list to store parsed fields
    List<String> fields = new ArrayList<>();

    // StringBuilder for accumulating current field value
    StringBuilder current = new StringBuilder();

    // Flag to track if we are inside a quoted field
    boolean inQuotes = false;

    // Iterate through each character in the line
    for (int i = 0; i < line.length(); i++) {
        char c = line.charAt(i);

        // Handle character based on current parser state
        if (inQuotes) {
            // We are inside a quoted field
            if (c == quoteChar) {
                // Check for escaped quote (double quote)
                if (i + 1 < line.length() && line.charAt(i + 1) == quoteChar) {
                    current.append(quoteChar);
                    i++; // Skip the next quote character
                } else {
                    // End of quoted field
                    inQuotes = false;
                }
            } else if (c == escapeChar) {
                // Handle escape sequences within quoted fields
                if (i + 1 < line.length()) {
                    current.append(line.charAt(i + 1));
                    i++;
                }
            } else {
                // Regular character inside quoted field
                current.append(c);
            }
        } else {
            // We are not inside a quoted field
            if (c == quoteChar && current.length() == 0) {
                // Start of a quoted field
                inQuotes = true;
            } else if (c == delimiter) {
                // Field separator found, add field and reset
                fields.add(current.toString());
                current = new StringBuilder();
            } else {
                // Regular character, append to current field
                current.append(c);
            }
        }
    }

    // Add the last field (after the final delimiter)
    fields.add(current.toString());

    // Return the list of parsed fields
    return fields;
}

pub fn format_invoice(invoice: &Invoice, customer: &Customer, items: &[LineItem]) -> String {
    let customer_name = customer.full_name();
    let customer_email = customer.email();
    let customer_address = customer.billing_address();
    let customer_tax_id = customer.tax_id();
    let invoice_number = invoice.number();
    let invoice_date = invoice.issue_date();
    let due_date = invoice.due_date();
    let mut total: f64 = 0.0;
    for item in items {
        total += item.quantity() as f64 * item.unit_price();
    }
    let tax = customer.calculate_tax(total);
    let grand_total = total + tax;
    format!(
        "Invoice: {}\nDate: {}\nDue: {}\nCustomer: {}\nEmail: {}\nAddress: {}\nTax ID: {}\nSubtotal: {:.2}\nTax: {:.2}\nTotal: {:.2}",
        invoice_number, invoice_date, due_date, customer_name, customer_email,
        customer_address, customer_tax_id, total, tax, grand_total
    )
}

