func HandleCheckout(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	sessionID := r.URL.Query().Get("session")
	if sessionID == "" {
		http.Error(w, "Missing session", http.StatusBadRequest)
		return
	}
	session, ok := sessions[sessionID]
	if !ok {
		http.Error(w, "Invalid session", http.StatusNotFound)
		return
	}
	if err := r.ParseForm(); err != nil {
		http.Error(w, "Invalid form data", http.StatusBadRequest)
		return
	}
	shippingName := r.FormValue("shipping_name")
	shippingAddr := r.FormValue("shipping_address")
	shippingCity := r.FormValue("shipping_city")
	shippingState := r.FormValue("shipping_state")
	shippingZip := r.FormValue("shipping_zip")
	if shippingName == "" || shippingAddr == "" || shippingCity == "" {
		http.Error(w, "Missing shipping info", http.StatusBadRequest)
		return
	}
	billingName := r.FormValue("billing_name")
	billingAddr := r.FormValue("billing_address")
	billingCity := r.FormValue("billing_city")
	billingState := r.FormValue("billing_state")
	billingZip := r.FormValue("billing_zip")
	sameAsShipping := r.FormValue("same_as_shipping")
	if sameAsShipping == "true" {
		billingName = shippingName
		billingAddr = shippingAddr
		billingCity = shippingCity
		billingState = shippingState
		billingZip = shippingZip
	}
	if billingName == "" || billingAddr == "" || billingCity == "" {
		http.Error(w, "Missing billing info", http.StatusBadRequest)
		return
	}
	paymentToken := r.FormValue("payment_token")
	if paymentToken == "" {
		http.Error(w, "Missing payment", http.StatusBadRequest)
		return
	}
	total := 0.0
	for _, item := range session.Cart.Items {
		total += float64(item.Quantity) * item.Price
	}
	taxRate := getTaxRate(shippingState)
	tax := total * taxRate
	grandTotal := total + tax
	if grandTotal > 100 {
		shipping = 0.0
	} else {
		shipping = 9.99
	}
	grandTotal += shipping
	charge, err := processPayment(paymentToken, grandTotal)
	if err != nil {
		http.Error(w, "Payment failed", http.StatusPaymentRequired)
		return
	}
	order := Order{
		SessionID:     sessionID,
		ShippingName:  shippingName,
		ShippingAddr:  shippingAddr,
		ShippingCity:  shippingCity,
		ShippingState: shippingState,
		ShippingZip:   shippingZip,
		BillingName:   billingName,
		BillingAddr:   billingAddr,
		BillingCity:   billingCity,
		BillingState:  billingState,
		BillingZip:    billingZip,
		Subtotal:      total,
		Tax:           tax,
		Shipping:      shipping,
		Total:         grandTotal,
		PaymentID:     charge.ID,
		Status:        "confirmed",
	}
	orders[order.ID] = order
	sendConfirmationEmail(order)
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(order)
}

function createShippingLabel(
  senderName: string,
