  senderZip: string,
  senderCountry: string,
  recipientName: string,
  recipientStreet: string,
  recipientCity: string,
  recipientZip: string,
  recipientCountry: string,
  weightKg: number,
  lengthCm: number,
  widthCm: number,
  heightCm: number,
): string {
  const sender = `${senderName}, ${senderStreet}, ${senderCity} ${senderZip}, ${senderCountry}`;
