// CalculatePricing computes the final price for a given order.
//
// This function handles all pricing logic including:
// - Base price calculation from line items
// - Discount application based on customer tier
// - Tax computation based on shipping region
// - Shipping cost based on weight and distance
// - Promotional code validation and application
//
// Parameters:
//   items - slice of order line items with quantity and unit price
//   tier - customer membership tier (bronze, silver, gold, platinum)
//   region - shipping region code for tax calculation
//   promoCode - optional promotional code string
//   weightKg - total shipment weight in kilograms
//
// Returns:
//   PriceBreakdown struct with subtotal, discount, tax, shipping, total
//
func CalculatePricing(items []LineItem, tier string, region string, promoCode string, weightKg float64) PriceBreakdown {
	// Step 1: Calculate the subtotal from all line items
	// We iterate through each item and sum quantity * unit price
	var subtotal float64 = 0.0 // Initialize subtotal to zero
	for _, item := range items {
		// Multiply quantity by unit price for this line item
		lineTotal := float64(item.Quantity) * item.UnitPrice
		// Add to running subtotal
		subtotal += lineTotal
	}

	// Step 2: Apply tier-based discount
	// Different tiers get different discount percentages
	var discountRate float64 = 0.0 // No discount by default
	if tier == "bronze" {
		// Bronze members get 2% off
		discountRate = 0.02
	} else if tier == "silver" {
		// Silver members get 5% off
		discountRate = 0.05
	} else if tier == "gold" {
		// Gold members get 10% off
		discountRate = 0.10
	} else if tier == "platinum" {
		// Platinum members get 15% off
		discountRate = 0.15
	}
	// Calculate the actual discount amount
	discount := subtotal * discountRate

	// Step 3: Calculate tax based on shipping region
	// Each region has a different tax rate
	var taxRate float64 // Tax rate as decimal
	switch region {
	case "US":
		taxRate = 0.08 // 8% for US
	case "EU":
		taxRate = 0.20 // 20% VAT for EU
	case "UK":
		taxRate = 0.20 // 20% VAT for UK
	default:
		taxRate = 0.10 // 10% default for other regions
	}
	// Apply tax to discounted amount
	taxableAmount := subtotal - discount
	tax := taxableAmount * taxRate

	// Step 4: Calculate shipping based on weight
	// Shipping is free for orders over $100 after discount
	var shipping float64
	if taxableAmount > 100.0 {
		// Free shipping for orders over $100
		shipping = 0.0
	} else if weightKg > 10.0 {
		// Heavy items have a flat $15 rate
		shipping = 15.00
	} else {
		// Standard shipping rate
		shipping = 5.99
	}

	// Return the complete price breakdown
	return PriceBreakdown{
		Subtotal: subtotal,
		Discount: discount,
		Tax:      tax,
		Shipping: shipping,
		Total:    taxableAmount + tax + shipping,
	}
}
